"""Hardware business outputs require Crawl before the first generated byte."""
import json
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent))
import hw_build
import hw_export
import hw_render_plan
sys.path.append(str(Path(__file__).resolve().parents[2] / "Luz-Crawl" / "scripts"))
from test_crawl_preflight import complete_fixture
from test_session_flow import select_design


def _session(tmp_path):
    folder = tmp_path / "001-hardware"
    raw = folder / "raw" / "04-hardware"
    raw.mkdir(parents=True)
    shutil.copyfile(Path(__file__).resolve().parents[1] / "examples" / "unmanned-gym.plan.json", raw / "plan.json")
    select_design(folder, "hardware", "hardware-plan", raw / "hardware-plan.html")
    select_design(folder, "hardware", "xlsx", folder / "硬件选型清单.xlsx")
    return folder, raw


@pytest.mark.parametrize("entry", ["build", "export", "render"])
def test_hardware_generation_without_crawl_writes_nothing(tmp_path, monkeypatch, capsys, entry):
    session, raw = _session(tmp_path)
    before = {p.relative_to(session): p.read_bytes() for p in session.rglob("*") if p.is_file()}
    monkeypatch.setattr(subprocess, "run", lambda *a, **k: subprocess.CompletedProcess(a[0], 0, "", ""))
    if entry == "build":
        monkeypatch.setattr(sys, "argv", ["hw_build.py", str(session)])
        code = hw_build.main()
    elif entry == "export":
        code = hw_export.main([str(session), "--spec-only"])
    else:
        monkeypatch.setattr(sys, "argv", ["hw_render_plan.py", str(raw / "plan.json"), str(raw / "hardware-plan.html"), "--force"])
        code = hw_render_plan.main()
    after = {p.relative_to(session): p.read_bytes() for p in session.rglob("*") if p.is_file()}
    output = capsys.readouterr()
    assert code != 0, "an unresearched hardware plan was generated"
    assert "Crawl" in output.out + output.err
    assert after == before


@pytest.mark.parametrize("entry", ["build", "export", "render"])
def test_hardware_generators_accept_verified_body_evidence(tmp_path, monkeypatch, entry):
    session, raw = _session(tmp_path)
    complete_fixture(session, "luz-system", "hardware")
    monkeypatch.setattr(subprocess, "run", lambda *a, **k: subprocess.CompletedProcess(a[0], 0, "", ""))
    if entry == "build":
        monkeypatch.setattr(sys, "argv", ["hw_build.py", str(session)])
        assert hw_build.main() == 0
    elif entry == "export":
        assert hw_export.main([str(session), "--spec-only"]) == 0
    else:
        monkeypatch.setattr(sys, "argv", ["hw_render_plan.py", str(raw / "plan.json"), str(raw / "hardware-plan.html")])
        assert hw_render_plan.main() == 0
    assert (raw / ("hardware-list.spec.json" if entry == "export" else "hardware-plan.html")).is_file()


def test_project_hardware_requires_its_architecture_stage(tmp_path):
    session, raw = _session(tmp_path)
    state = tmp_path / "project-state"
    state.mkdir()
    (state / "project.json").write_text(json.dumps({"crawl": {"evidence_index": "00-crawl"}}), encoding="utf-8")
    manifest = session / "raw" / "99-delivery" / "MANIFEST.json"
    manifest.parent.mkdir()
    manifest.write_text(json.dumps({"project": {"state_root": str(state)}}), encoding="utf-8")
    complete_fixture(session, "luz-system", "hardware")
    complete_fixture(state, "luz-system", "design")
    before = {p: p.read_bytes() for p in session.rglob("*") if p.is_file()}
    assert hw_export.main([str(session), "--spec-only"]) != 0
    assert {p: p.read_bytes() for p in session.rglob("*") if p.is_file()} == before
    record = complete_fixture(state, "luz-system", "architecture")
    assert hw_export.main([str(session), "--spec-only"]) == 0
    proof = json.loads(record.read_text(encoding="utf-8"))
    (Path(proof["sources"][0]["archive"]) / "content.json").write_text('{"text":"changed"}', encoding="utf-8")
    saved = (raw / "hardware-list.spec.json").read_bytes()
    assert hw_export.main([str(session), "--spec-only"]) != 0
    assert (raw / "hardware-list.spec.json").read_bytes() == saved


def test_explicit_project_environment_is_used_without_a_session_manifest(tmp_path, monkeypatch):
    session, raw = _session(tmp_path)
    state = tmp_path / "state"
    state.mkdir()
    (state / "project.json").write_text(json.dumps({"name": "context fixture", "crawl": {"evidence_index": "00-crawl"}}), encoding="utf-8")
    monkeypatch.setenv("LUZ_PROJECT_ROOT", str(state))
    complete_fixture(session, "luz-system", "hardware")
    assert hw_export.main([str(session), "--spec-only"]) != 0
    assert not (raw / "hardware-list.spec.json").exists()
    complete_fixture(state, "luz-system", "architecture")
    assert hw_export.main([str(session), "--spec-only"]) == 0


def test_excel_export_uses_the_checked_internal_design_renderer(tmp_path, monkeypatch):
    session, _ = _session(tmp_path)
    complete_fixture(session, "luz-system", "hardware")

    def no_nested_business_cli(*args, **kwargs):
        raise AssertionError("internal formatting must not invoke a second business CLI")

    monkeypatch.setattr(subprocess, "run", no_nested_business_cli)
    assert hw_export.main([str(session)]) == 0
    assert (session / "硬件选型清单.xlsx").is_file()
